// One sealed code that puts a whole profile back on a new device.
//
// The point of this module is that a lost, wiped or replaced device stops being
// a lost account. It produces a single text code — everything the extension
// stores, minus the things that belong to one machine — locked with a key that
// only the person holds. Nothing in here can open it again: there is no server
// secret, no key baked into the code, and no way to recover the data from the
// code alone.
//
// How it is locked:
//
//   * a recovery key of 20 random bytes (160 bits), generated by the browser's
//     CSPRNG and written in Crockford base32 — no I, L, O or U, so a key
//     written down by hand does not become a different key;
//   * that key is stretched with PBKDF2-HMAC-SHA-256 at 600,000 rounds over a
//     fresh 16-byte salt, so even a short or mistyped key costs an attacker
//     real hardware time per guess;
//   * the profile is encrypted with AES-256-GCM (a fresh 12-byte IV per seal,
//     128-bit tag, the format string as additional authenticated data), which
//     both hides the data and proves nobody altered it;
//   * the envelope carries the salt, the IV and the round count, so a code made
//     today still opens if the defaults change later.
//
// Guessing is not the way in, and neither is reading the file: the ciphertext is
// indistinguishable from random. The only thing that opens a code is the exact
// recovery key it was sealed with — which is why the settings page tells the
// person to keep it somewhere other than this device.
export const CODE_PREFIX = "LUMA1";
export const KEY_BYTES = 20;
export const ITERATIONS = 600000;
// A code is only ever opened with the rounds it was sealed with, but a hostile
// file must not be able to freeze the page by asking for an hour of stretching.
const MIN_ITERATIONS = 1000;
const MAX_ITERATIONS = 2000000;
const SALT_BYTES = 16;
const IV_BYTES = 12;
const AAD = new TextEncoder().encode("luma-vault-v1");

// Crockford base32: digits then letters with I, L, O and U removed.
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

function toBase32(bytes) {
  let out = "";
  let buffer = 0;
  let bits = 0;
  for (let index = 0; index < bytes.length; index += 1) {
    buffer = ((buffer << 8) | bytes[index]) & 0xffff;
    bits += 8;
    while (bits >= 5) {
      out += ALPHABET[(buffer >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) out += ALPHABET[(buffer << (5 - bits)) & 31];
  return out;
}

function fromBase32(text) {
  const clean = String(text || "");
  if (!clean) return null;
  const bytes = [];
  let buffer = 0;
  let bits = 0;
  for (let index = 0; index < clean.length; index += 1) {
    const value = ALPHABET.indexOf(clean[index]);
    if (value === -1) return null;
    buffer = ((buffer << 5) | value) & 0xffff;
    bits += 5;
    if (bits >= 8) {
      bytes.push((buffer >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return new Uint8Array(bytes);
}

function toB64Url(bytes) {
  let binary = "";
  for (let index = 0; index < bytes.length; index += 1) binary += String.fromCharCode(bytes[index]);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromB64Url(text) {
  const padded = String(text || "")
    .replace(/-/g, "+")
    .replace(/_/g, "/");
  if (!/^[A-Za-z0-9+/]*$/.test(padded)) throw refused("bad-code", "That is not a backup code.");
  const binary = atob(padded + "=".repeat((4 - (padded.length % 4)) % 4));
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function refused(reason, message) {
  const error = new Error(message);
  error.reason = reason;
  return error;
}

// A key typed from a printout: case, spaces and dashes do not matter, and the
// characters Crockford drops (O for zero, I and L for one) are read the way they
// were meant.
export function normalizeRecoveryKey(value) {
  return String(value || "")
    .toUpperCase()
    .replace(/[^0-9A-Z]/g, "")
    .replace(/O/g, "0")
    .replace(/[IL]/g, "1");
}

// Four-character groups, which is how a key is written down and read back.
export function groupRecoveryKey(key) {
  const clean = normalizeRecoveryKey(key);
  const groups = [];
  for (let index = 0; index < clean.length; index += 4) groups.push(clean.slice(index, index + 4));
  return groups.join("-");
}

export function newRecoveryKey() {
  return groupRecoveryKey(toBase32(crypto.getRandomValues(new Uint8Array(KEY_BYTES))));
}

export function recoveryKeyLooksValid(value) {
  return normalizeRecoveryKey(value).length === Math.ceil((KEY_BYTES * 8) / 5);
}

async function deriveKey(recoveryKey, salt, iterations) {
  const raw = fromBase32(normalizeRecoveryKey(recoveryKey));
  if (!raw || raw.length !== KEY_BYTES) {
    throw refused("bad-key", "That recovery key is not the right length.");
  }
  const base = await crypto.subtle.importKey("raw", raw, "PBKDF2", false, ["deriveKey"]);
  return crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations, hash: "SHA-256" },
    base,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

function iterationCount(value) {
  const count = Number(value);
  if (!isFinite(count) || count < MIN_ITERATIONS || count > MAX_ITERATIONS) return null;
  return Math.round(count);
}

// Seals any JSON-shaped value into one pastable line.
export async function seal(payload, recoveryKey, options) {
  const iterations = iterationCount((options && options.iterations) || ITERATIONS);
  if (!iterations) throw refused("bad-iterations", "Unsupported key-stretching rounds.");
  const salt = crypto.getRandomValues(new Uint8Array(SALT_BYTES));
  const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES));
  const key = await deriveKey(recoveryKey, salt, iterations);
  const plaintext = new TextEncoder().encode(JSON.stringify(payload));
  const sealed = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv, additionalData: AAD, tagLength: 128 },
    key,
    plaintext
  );
  const envelope = {
    v: 1,
    kdf: "PBKDF2-SHA-256",
    iter: iterations,
    cipher: "AES-256-GCM",
    salt: toB64Url(salt),
    iv: toB64Url(iv),
    ct: toB64Url(new Uint8Array(sealed)),
  };
  return CODE_PREFIX + "." + toB64Url(new TextEncoder().encode(JSON.stringify(envelope)));
}

function readEnvelope(code) {
  const text = String(code || "").replace(/\s+/g, "");
  const at = text.indexOf(CODE_PREFIX + ".");
  if (at === -1) throw refused("bad-code", "That is not a backup code.");
  const body = text.slice(at + CODE_PREFIX.length + 1);
  let envelope;
  try {
    envelope = JSON.parse(new TextDecoder().decode(fromB64Url(body)));
  } catch (_error) {
    throw refused("bad-code", "That backup code is damaged.");
  }
  if (!envelope || envelope.v !== 1 || envelope.cipher !== "AES-256-GCM") {
    throw refused("bad-code", "That backup code is from a newer version.");
  }
  const iterations = iterationCount(envelope.iter);
  if (!iterations) throw refused("bad-code", "That backup code is damaged.");
  return { envelope, iterations };
}

// Opens a sealed code. A wrong key, a single flipped character in the code and a
// different device all land on the same answer: the box does not open.
export async function open(code, recoveryKey) {
  const { envelope, iterations } = readEnvelope(code);
  const salt = fromB64Url(envelope.salt);
  const iv = fromB64Url(envelope.iv);
  const body = fromB64Url(envelope.ct);
  if (!salt.length || !iv.length || !body.length) throw refused("bad-code", "That backup code is damaged.");
  const key = await deriveKey(recoveryKey, salt, iterations);
  let plaintext;
  try {
    plaintext = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv, additionalData: AAD, tagLength: 128 },
      key,
      body
    );
  } catch (_error) {
    throw refused("wrong-key", "That recovery key does not open this code.");
  }
  try {
    return JSON.parse(new TextDecoder().decode(plaintext));
  } catch (_error) {
    throw refused("bad-code", "That backup code does not hold a profile.");
  }
}

// True for anything shaped like a code, so the settings page can tell a paste
// from a mistyped recovery key before it runs the expensive part.
export function looksLikeCode(value) {
  return String(value || "").indexOf(CODE_PREFIX + ".") !== -1;
}
